 34| const UserPathSchema = z.object({ userId: UserIdSchema });
 35| const UserListSchema = pageSchema(UserSchema);
 36| 
 37| function userKey(user: User): string {
 38|   return `${user.createdAt}|${user.id}`;
 39| }
 40| 
 41| function problemForMissingUser(userId: string) {
 42|   return notFound(`User ${userId} was not found.`);
 43| }
 44| 
 45| /**
 46|  * Mount resource routers here, e.g. `app.use(usersRouter)`.
 47|  * Routers register full versioned paths (`/v1/users`, `/v1/users/:userId`).
 48|  */
 49| export function registerRoutes(app: Router): void {
 50|   const users = new Map<string, User>();
 51|   const userIdsByEmail = new Map<string, string>();
 52| 
 53|   const usersRouter = Router();
 54| 
 55|   usersRouter.get('/v1/users', (req, res) => {
 56|     const query = CursorQuerySchema.parse(req.query);
 57|     const page = paginate([...users.values()], query, userKey);
 58|     const body = UserListSchema.parse({ data: page.data.map((user) => UserSchema.parse(user)), nextCursor: page.nextCursor });
 59|     res.json(body);
 60|   });
 61| 
 62|   usersRouter.post('/v1/users', idempotency(), (req, res) => {
 63|     const body = CreateUserBodySchema.parse(req.body);
 64|     if (userIdsByEmail.has(body.email)) {
 65|       throw conflict(`A user with email ${body.email} already exists.`);
 66|     }
 67| 
 68|     const now = new Date().toISOString();
 69|     const user = UserSchema.parse({
 70|       id: crypto.randomUUID(),
 71|       email: body.email,
 72|       name: body.name,
 73|       role: body.role,
 74|       createdAt: now,
 75|       updatedAt: now,
 76|     });
 77| 
 78|     users.set(user.id, user);
 79|     userIdsByEmail.set(user.email, user.id);
 80| 
 81|     res.location(`/v1/users/${user.id}`).status(201).json(UserSchema.parse(user));
 82|   });
 83| 
 84|   usersRouter.get('/v1/users/:userId', (req, res) => {
 85|     const { userId } = UserPathSchema.parse(req.params);
 86|     const user = users.get(userId);
 87|     if (user === undefined) throw problemForMissingUser(userId);
 88|     res.json(UserSchema.parse(user));
 89|   });
 90| 
 91|   usersRouter.patch('/v1/users/:userId', idempotency(), (req, res) => {
 92|     const { userId } = UserPathSchema.parse(req.params);
 93|     const patch = PatchUserBodySchema.parse(req.body);
 94|     const current = users.get(userId);
 95|     if (current === undefined) throw problemForMissingUser(userId);
 96| 
 97|     if (patch.email !== undefined) {
 98|       const ownerId = userIdsByEmail.get(patch.email);
 99|       if (ownerId !== undefined && ownerId !== userId) {
100|         throw conflict(`A user with email ${patch.email} already exists.`);
101|       }
102|     }
103| 
104|     const updated = UserSchema.parse({
105|       ...current,
106|       ...patch,
107|       updatedAt: new Date().toISOString(),
108|     });
109| 
110|     if (updated.email !== current.email) {
111|       userIdsByEmail.delete(current.email);
112|       userIdsByEmail.set(updated.email, updated.id);
113|     }
114|     users.set(updated.id, updated);
115| 
116|     res.json(UserSchema.parse(updated));
117|   });
118| 
119|   usersRouter.delete('/v1/users/:userId', (req, res) => {
120|     const { userId } = UserPathSchema.parse(req.params);
121|     const user = users.get(userId);
122|     if (user === undefined) throw problemForMissingUser(userId);
123|     users.delete(userId);
124|     userIdsByEmail.delete(user.email);
125|     res.status(204).end();
126|   });
127| 
128|   app.use(usersRouter);
129| }
